import React, { useState, useEffect, useContext } from "react";
import { AuthContext } from "../context/AuthContext";
import API from "../api";
import "./AdminDashboard.css";

const AdminDashboard = () => {
  const { user } = useContext(AuthContext);
  const [events, setEvents] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [editingEvent, setEditingEvent] = useState(null);
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState("all");
  const [form, setForm] = useState({
    title: "",
    description: "",
    category: "Academic",
    date: "",
    startTime: "",
    endTime: "",
    maxRegistrations: 50,
    organizerName: "",
    organizerContact: "",
    hall: "",
    department: "",
    tags: ""
  });

  useEffect(() => {
    if (user?.role === "admin") {
      fetchEvents();
    }
  }, [user]);

  const fetchEvents = async () => {
    try {
      const res = await API.get("/events/admin/all");
      setEvents(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      const eventData = { ...form, tags: form.tags.split(",").map(t => t.trim()) };
      if (editingEvent) {
        await API.put(`/events/${editingEvent._id}`, eventData);
        alert("Event updated successfully!");
      } else {
        await API.post("/events", eventData);
        alert("Event created successfully!");
      }
      setForm({
        title: "",
        description: "",
        category: "Academic",
        date: "",
        startTime: "",
        endTime: "",
        maxRegistrations: 50,
        organizerName: "",
        organizerContact: "",
        hall: "",
        department: "",
        tags: ""
      });
      setEditingEvent(null);
      setShowForm(false);
      fetchEvents();
    } catch (err) {
      alert("Error: " + (err.response?.data?.msg || err.message));
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (event) => {
    setEditingEvent(event);
    setForm({
      title: event.title,
      description: event.description,
      category: event.category,
      date: event.date.split("T")[0],
      startTime: event.startTime,
      endTime: event.endTime,
      maxRegistrations: event.maxRegistrations,
      organizerName: event.organizerName,
      organizerContact: event.organizerContact,
      hall: event.hall,
      department: event.department,
      tags: event.tags?.join(", ") || ""
    });
    setShowForm(true);
  };

  const handleDelete = async (id) => {
    if (window.confirm("Are you sure you want to delete this event?")) {
      try {
        await API.delete(`/events/${id}`);
        alert("Event deleted successfully!");
        fetchEvents();
      } catch (err) {
        alert("Error deleting event");
      }
    }
  };

  const handleToggleFeatured = async (id) => {
    try {
      await API.patch(`/events/${id}/featured`);
      fetchEvents();
    } catch (err) {
      alert("Error updating event");
    }
  };

  const handleStatusChange = async (id, status) => {
    try {
      await API.patch(`/events/${id}/status`, { status });
      fetchEvents();
    } catch (err) {
      alert("Error updating status");
    }
  };

  const filterEvents = () => {
    if (activeTab === "all") return events;
    return events.filter(e => e.status === activeTab);
  };

  const displayEvents = filterEvents();

  if (user?.role !== "admin") {
    return <div className="admin-container"><p>Access denied</p></div>;
  }

  return (
    <div className="admin-container">
      <div className="admin-header">
        <h1>Admin Dashboard</h1>
        <p>Manage all events and programs</p>
      </div>

      <div className="admin-toolbar">
        <button 
          className="btn btn-primary"
          onClick={() => { setShowForm(!showForm); setEditingEvent(null); }}
        >
          {showForm ? "✕ Cancel" : "+ Create New Event"}
        </button>
      </div>

      {showForm && (
        <div className="event-form-container">
          <h2>{editingEvent ? "Edit Event" : "Create New Event"}</h2>
          <form onSubmit={handleSubmit} className="event-form">
            <div className="form-row">
              <div className="form-group">
                <label>Event Title *</label>
                <input
                  type="text"
                  required
                  value={form.title}
                  onChange={(e) => setForm({ ...form, title: e.target.value })}
                  placeholder="Enter event title"
                />
              </div>
              <div className="form-group">
                <label>Category</label>
                <select value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })}>
                  <option value="Academic">Academic</option>
                  <option value="Sports">Sports</option>
                  <option value="Cultural">Cultural</option>
                  <option value="Workshop">Workshop</option>
                  <option value="Seminar">Seminar</option>
                  <option value="Conference">Conference</option>
                  <option value="Social">Social</option>
                </select>
              </div>
            </div>

            <div className="form-group">
              <label>Description</label>
              <textarea
                value={form.description}
                onChange={(e) => setForm({ ...form, description: e.target.value })}
                placeholder="Event description"
                rows="4"
              />
            </div>

            <div className="form-row">
              <div className="form-group">
                <label>Date *</label>
                <input
                  type="date"
                  required
                  value={form.date}
                  onChange={(e) => setForm({ ...form, date: e.target.value })}
                />
              </div>
              <div className="form-group">
                <label>Start Time</label>
                <input
                  type="time"
                  value={form.startTime}
                  onChange={(e) => setForm({ ...form, startTime: e.target.value })}
                />
              </div>
              <div className="form-group">
                <label>End Time</label>
                <input
                  type="time"
                  value={form.endTime}
                  onChange={(e) => setForm({ ...form, endTime: e.target.value })}
                />
              </div>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label>Max Registrations</label>
                <input
                  type="number"
                  value={form.maxRegistrations}
                  onChange={(e) => setForm({ ...form, maxRegistrations: parseInt(e.target.value) })}
                  min="1"
                />
              </div>
              <div className="form-group">
                <label>Department</label>
                <input
                  type="text"
                  value={form.department}
                  onChange={(e) => setForm({ ...form, department: e.target.value })}
                  placeholder="e.g., Computer Science"
                />
              </div>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label>Organizer Name</label>
                <input
                  type="text"
                  value={form.organizerName}
                  onChange={(e) => setForm({ ...form, organizerName: e.target.value })}
                />
              </div>
              <div className="form-group">
                <label>Organizer Contact</label>
                <input
                  type="email"
                  value={form.organizerContact}
                  onChange={(e) => setForm({ ...form, organizerContact: e.target.value })}
                />
              </div>
            </div>

            {/* Image URL removed per request */}

            <div className="form-group">
              <label>Tags (comma separated)</label>
              <input
                type="text"
                value={form.tags}
                onChange={(e) => setForm({ ...form, tags: e.target.value })}
                placeholder="tag1, tag2, tag3"
              />
            </div>

            <button type="submit" disabled={loading} className="btn btn-success">
              {loading ? "Saving..." : editingEvent ? "Update Event" : "Create Event"}
            </button>
          </form>
        </div>
      )}

      <div className="admin-tabs">
        <button
          className={`tab ${activeTab === "all" ? "active" : ""}`}
          onClick={() => setActiveTab("all")}
        >
          All Events ({events.length})
        </button>
        <button
          className={`tab ${activeTab === "active" ? "active" : ""}`}
          onClick={() => setActiveTab("active")}
        >
          Active ({events.filter(e => e.status === "active").length})
        </button>
        <button
          className={`tab ${activeTab === "completed" ? "active" : ""}`}
          onClick={() => setActiveTab("completed")}
        >
          Completed ({events.filter(e => e.status === "completed").length})
        </button>
        <button
          className={`tab ${activeTab === "cancelled" ? "active" : ""}`}
          onClick={() => setActiveTab("cancelled")}
        >
          Cancelled ({events.filter(e => e.status === "cancelled").length})
        </button>
      </div>

      <div className="events-grid">
        {displayEvents.length === 0 ? (
          <p className="no-events">No events found</p>
        ) : (
          displayEvents.map((event) => (
            <div key={event._id} className="event-card admin-event-card">
              <div className="event-card-header">
                <div className={`event-status ${event.status}`}>{event.status}</div>
                {event.featured && <div className="featured-badge">⭐ Featured</div>}
              </div>
              <div className="event-card-content">
                <h3>{event.title}</h3>
                <p className="event-category">{event.category}</p>
                <p className="event-date">📅 {new Date(event.date).toLocaleDateString()}</p>
                <p className="event-time">🕐 {event.startTime} - {event.endTime}</p>
                <p className="event-registrations">👥 {event.currentRegistrations}/{event.maxRegistrations}</p>
              </div>
              <div className="event-card-actions">
                <button className="btn btn-sm btn-edit" onClick={() => handleEdit(event)}>Edit</button>
                <button 
                  className="btn btn-sm btn-danger" 
                  onClick={() => handleDelete(event._id)}
                >
                  Delete
                </button>
                <button 
                  className={`btn btn-sm ${event.featured ? 'btn-warning' : 'btn-secondary'}`}
                  onClick={() => handleToggleFeatured(event._id)}
                >
                  {event.featured ? "Unfeature" : "Feature"}
                </button>
                <select
                  className="status-select"
                  value={event.status}
                  onChange={(e) => handleStatusChange(event._id, e.target.value)}
                >
                  <option value="active">Active</option>
                  <option value="completed">Completed</option>
                  <option value="cancelled">Cancelled</option>
                </select>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default AdminDashboard;
